return ['project-id-version'=>'Easy Form Builder 4.3.1','report-msgid-bugs-to'=>'https://whitestudio.team/','mime-version'=>'1.0','content-type'=>'text/plain; charset=UTF-8','content-transfer-encoding'=>'8bit','pot-creation-date'=>'2026-10-29 00:00+0000','x-generator'=>'EFB tests/core-i18n/build.php','x-domain'=>'easy-form-builder','po-revision-date'=>'2026-10-29 21:18+0000','last-translator'=>'WhiteStudio <hi@whitestudio.team>','language-team'=>'fa_IR','language'=>'fa_IR','plural-forms'=>'nplurals=2; plural=n > 1;','messages'=>['$NN/year'=>'1.420.00تومان','% not found'=>'% پیدا نشد','%1$s %2$s & %3$s'=>'%1$s %2$s و %3$s','%1$s + %2$s'=>'%1$s + %2$s','%1$s cannot run because required PHP functions are unavailable (%2$s). Ask your hosting provider to enable the required PHP extension or remove the listed functions from disable_functions in php.ini.'=>'%1$s نمی‌تواند اجرا شود، زیرا توابع موردنیاز PHP در دسترس نیستند (%2$s). لطفاً از ارائه‌دهنده هاست خود بخواهید افزونه (Extension) موردنیاز PHP را فعال کند یا توابع فهرست‌شده را از مقدار disable_functions در فایل php.ini حذف نماید.','%1$s could not install its translation into %2$s on %3$s.'=>'%1$s نتوانست ترجمه خود به %2$s را در %3$s نصب کند.','%1$s is downloading its translation into %2$s. This takes a few seconds, and the page reloads by itself.'=>'%1$s در حال دانلود ترجمه خود به %2$s است. این کار چند ثانیه طول می‌کشد و صفحه به‌صورت خودکار دوباره بارگذاری می‌شود.','%1$s is installing its language files (%2$s)&hellip;'=>'%1$s در حال نصب فایل‌های زبان خود (%2$s) است&hellip;','%1$s on %2$s could not download its translation files from the WhiteStudio server (%3$s), because the server this website runs on cannot connect to it.'=>'%1$s در %2$s نتوانست فایل‌های ترجمه خود را از سرور WhiteStudio (%3$s) دانلود کند، زیرا سروری که این وب‌سایت روی آن اجرا می‌شود نمی‌تواند به آن سرور متصل شود.','%s Buttons | Align'=>'دکمه‌های %s | تراز','%s Checked Color'=>'رنگ حالت انتخاب‌شده %s','%s Day'=>'%s روز','%s Days'=>'%s روز','%s Description | Align'=>'%s توضیحات | تراز','%s Details'=>'جزئیات %s','%s Error Log'=>'گزارش خطای %s','%s Failures'=>'خطاهای %s','%s Label Position'=>'موقعیت برچسب %s','%s Label size'=>'اندازه برچسب %s','%s Label | Align'=>'%s برچسب | تراز','%s Location'=>'موقعیت %s','%s OFF'=>'%s تخفیف','%s Payment Add-on'=>'افزودنی پرداخت %s','%s color'=>'رنگ %s','%s complete'=>'%s تکمیل شده','%s copied!'=>'%s کپی شد!','%s days'=>'%s روز','%s is currently unavailable.'=>'%s در حال حاضر در دسترس نیست.','%s keeps working, in English.'=>'%s همچنان به زبان انگلیسی کار می‌کند.','%s list'=>'فهرست %s','%s not found'=>'%s یافت نشد','%s notification'=>'آگاه‌سازی %s','%s of 5 steps done'=>'%s مرحله از ۵ مرحله انجام شد','%s unsaved changes'=>'%s تغییر ذخیره‌نشده','%s views'=>'%s بازدیدها','%s width'=>'عرض %s','%s%%'=>'%s%%','%s: language files installed.'=>'%s: فایل‌های زبان نصب شدند.','(Avoid adding JavaScript or jQuery codes to HTML for security reasons.)'=>'(به دلایل امنیتی، از افزودن کدهای JavaScript یا jQuery به HTML خودداری کنید.)','(Video or Audio)'=>'(ویدئو یا صوت)','(currently enabled and paused)'=>'(اکنون فعال است، اما موقتاً متوقف شده)','(not enabled)'=>'(فعال نیست)','/ 100'=>'/ ۱۰۰','0 = no caching'=>'۰ = بدون کش','1 unsaved change'=>'۱ تغییر ذخیره‌نشده','1. Allow file changes by removing DISALLOW_FILE_MODS from wp-config.php, or install the files yourself as described below.'=>'۱. با حذف DISALLOW_FILE_MODS از wp-config.php اجازه تغییر فایل‌ها را بدهید، یا فایل‌ها را خودتان طبق توضیحات زیر نصب کنید.','1. Ask your hosting provider to allow outgoing HTTPS connections (port 443) from this server to %s.'=>'۱. از ارائه‌دهنده میزبانی خود بخواهید اتصال‌های خروجی HTTPS (پورت 443) را از این سرور به %s مجاز کند.','1. Ask your hosting provider to allow outgoing HTTPS connections (port 443) from this server to %s. The plugin installs the translation by itself as soon as it can connect.'=>'۱. از ارائه‌دهنده میزبانی خود بخواهید اتصال‌های خروجی HTTPS (پورت 443) را از این سرور به %s مجاز کند. افزونه به‌محض برقراری اتصال، ترجمه را به‌صورت خودکار نصب می‌کند.','1. Ask your hosting provider to let WordPress write files directly, or install the files yourself as described below.'=>'۱. از ارائه‌دهنده میزبانی خود بخواهید به وردپرس اجازه دهد فایل‌ها را مستقیماً بنویسد، یا فایل‌ها را خودتان طبق توضیحات زیر نصب کنید.','1. Make the folder %s writable by WordPress. The plugin installs the translation by itself afterwards.'=>'۱. پوشه %s را برای وردپرس قابل نوشتن کنید. افزونه پس از آن ترجمه را به‌صورت خودکار نصب می‌کند.','1080p (Full HD)'=>'۱۰۸۰p، کیفیت Full HD','2. Or install the translation files yourself by following this short guide:'=>'۲. یا فایل‌های ترجمه را خودتان با دنبال کردن این راهنمای کوتاه نصب کنید:','2. Or install the translation yourself, in a few minutes:'=>'۲. یا ترجمه را خودتان در چند دقیقه نصب کنید:','480p'=>'۴۸۰p','5 Point Scale'=>'مقیاس ۵ امتیازی','720p (HD)'=>'۷۲۰p، کیفیت HD','A New Message has been Received.'=>'یک پیام جدید دریافت شد.','A Pro version feature'=>'از امکانات نسخه Pro','A complete email health report — including your spam score, deliverability details, and recommendations — will be sent to %s within the next few minutes.'=>'گزارش کامل سلامت ایمیل، شامل امتیاز اسپم، جزئیات تحویل و پیشنهادها، تا چند دقیقه دیگر به %s ارسال خواهد شد.','A complete email health report — including your spam score, deliverability details, and recommendations — will be sent within the next few minutes to'=>'گزارش کامل سلامت ایمیل — شامل امتیاز هرزنامه، جزئیات تحویل‌پذیری و پیشنهادها — تا چند دقیقه دیگر به این نشانی ارسال می‌شود:','A detailed HTML report with full diagnostics is being prepared and emailed to you.'=>'گزارش کامل HTML شامل همه اطلاعات عیب‌یابی در حال آماده‌سازی است و برای شما ایمیل خواهد شد.','A discount code was already issued for this username. Check that earlier email, or contact support.'=>'قبلاً برای این نام کاربری یک کد تخفیف صادر شده است. ایمیل قبلی را بررسی کنید یا با پشتیبانی تماس بگیرید.','A feature I needed is missing'=>'قابلیتی که نیاز داشتم وجود ندارد','A form, response box or upload request encountered an error. Some requests may have recovered automatically; counts are not lost submissions. Browser reports are unverified; a 403 alone does not prove a cache or firewall problem. Submission status may be unknown.'=>'یک درخواست فرم، جعبه پاسخ یا بارگذاری با خطا مواجه شد. ممکن است برخی درخواست‌ها به‌صورت خودکار بازیابی شده باشند؛ این شمارش‌ها به معنای از دست رفتن ارسال‌ها نیست. گزارش‌های مرورگر تأیید نشده‌اند؛ خطای 403 به‌تنهایی دلیلی بر وجود مشکل کش یا دیواره آتش نیست. وضعیت ارسال ممکن است ناشناخته باشد.','A hosting server usually sends mail without a trusted signature, which is what pushes your form emails into the spam folder or stops them arriving at all. The standard fix is to send through an SMTP service.'=>'سرور میزبانی معمولاً ایمیل را بدون امضای معتبر ارسال می‌کند؛ همین موضوع باعث می‌شود ایمیل‌های فرم شما وارد پوشه هرزنامه شوند یا اصلاً نرسند. راه‌حل استاندارد، ارسال از طریق یک سرویس SMTP است.','A little more detail, please - one sentence about what broke is enough.'=>'لطفاً کمی توضیح بیشتر بدهید؛ یک جمله درباره چیزی که درست کار نکرد کافی است.','A new user has registered on your website.'=>'یک کاربر جدید در وب‌سایت شما ثبت‌نام کرده است.','A required Google API is not enabled for this project. Enable Google Sheets API and Google Drive API in Google Cloud Console, then try again.'=>'یک API موردنیاز گوگل برای این پروژه فعال نشده است. Google Sheets API و Google Drive API را در کنسول Google Cloud فعال کنید و دوباره تلاش کنید.','A sending service delivers your form emails from its own trusted servers. Install the official plugin with one click, sign in and connect; most services also give you the SPF and DKIM records to copy.'=>'یک سرویس ارسال، ایمیل‌های فرم شما را از سرورهای مورد اعتماد خود تحویل می‌دهد. افزونه رسمی را با یک کلیک نصب کنید، وارد شوید و متصل شوید؛ بیشتر سرویس‌ها رکوردهای SPF و DKIM را هم برای کپی کردن در اختیار شما قرار می‌دهند.','A test email was sent. Waiting for delivery confirmation…'=>'یک ایمیل آزمایشی ارسال شد. در انتظار تأیید تحویل…','A unique address is being generated for this test.'=>'یک نشانی یکتا برای این آزمایش در حال ایجاد است.','API Auto-Populate Integration is Active'=>'یکپارچه‌سازی پرکردن خودکار API فعال است','API Endpoint URL'=>'نشانی نقطه پایانی API','API Field Name'=>'نام فیلد API','API KEY'=>'کلید API','API Response Field'=>'فیلد پاسخ API','API connection ID is required'=>'شناسه اتصال API الزامی است','API connection not found or disabled'=>'اتصال API پیدا نشد یا غیرفعال است','API endpoint URL is required'=>'نشانی نقطه پایانی API الزامی است','API returned error: %d'=>'API خطای %d را برگرداند','Accent'=>'رنگ تأکیدی','Accept custom orders with product selection and payment.'=>'سفارش‌های سفارشی را همراه با انتخاب محصول و پرداخت دریافت کنید.','Acceptable file types'=>'انواع فایل قابل قبول','Accepted for sending; delivery not confirmed yet'=>'برای ارسال پذیرفته شد؛ تحویل هنوز تأیید نشده است','Access denied'=>'دسترسی رد شد','Access denied. Make sure the spreadsheet is shared with the service account email as Editor.'=>'دسترسی رد شد. مطمئن شوید صفحه‌گسترده با ایمیل حساب سرویس و با سطح دسترسی «ویرایشگر» به اشتراک گذاشته شده است.','Accounting & Sell question'=>'پرسش حسابداری و فروش','Action needed: Easy Form Builder Pro is paused on %s'=>'نیاز به اقدام: نسخه حرفه‌ای فرم ساز آسان در %s متوقف شده است','Actions'=>'اقدامات','Activate Pro version'=>'فعال‌سازی نسخه ویژه','Activate Pro version for more features and unlimited access to all plugin services.'=>'برای قابلیت‌های بیشتر و دسترسی نامحدود به همه خدمات افزونه، نسخه ویژه را فعال کنید.','Activate add-ons'=>'فعال‌سازی افزودنی‌ها','Activated'=>'فعال‌شده','Activation Code'=>'کد فعال‌سازی','Activation code'=>'کد فعال‌سازی','Activation of offline form mode.'=>'فعال‌سازی حالت آفلاین فرم','Active'=>'فعال','Add'=>'افزودن','Add API Connection'=>'افزودن اتصال API','Add Easy Form Builder forms to your page'=>'فرم‌های فرم‌ساز آسان را به برگه خود اضافه کنید','Add Google reCAPTCHA to the form'=>'افزودن reCAPTCHA به فرم','Add Link'=>'افزودن پیوند','Add New API Connection'=>'افزودن اتصال API جدید','Add custom CSS classes for styling.'=>'برای استایل‌دهی، کلاس‌های CSS سفارشی اضافه کنید.','Add forms created with Easy Form Builder'=>'فرم‌های ایجادشده با فرم‌ساز آسان را اضافه کنید','Add image URL'=>'افزودن نشانی تصویر','Add the SPF and DKIM records to your domain settings.'=>'رکوردهای SPF و DKIM را به تنظیمات دامنه خود اضافه کنید.','Add this shortcode inside a tag to display the title of the email.'=>'برای نمایش عنوان ایمیل این کدکوتاه را در درون یک تگ اضافه کنید.','Add this shortcode inside an HTML tag to display the message content of an email.'=>'برای نمایش محتوای پیام ایمیل، این کدکوتاه را درون یک تگ HTML اضافه کنید.','Add this shortcode within an HTML tag to display the Website URL.'=>'برای نمایش URL وب‌سایت، این کدکوتاه را درون یک تگ HTML اضافه کنید.','Add your own font by entering the font name and its CSS URL (e.g. Google Fonts link).'=>'با وارد کردن نام فونت و نشانی CSS آن (برای مثال پیوند Google Fonts)، فونت دلخواه خود را اضافه کنید.','Add-on'=>'افزودنی','Add-on affected: %s'=>'افزودنی تحت تأثیر: %s','Add-on directory is ready for file operations'=>'پوشه افزودنی برای عملیات فایل آماده است','Add-on folder'=>'پوشه افزودنی','Add-ons'=>'افزودنی‌ها','Add-ons & extensions'=>'افزودنی‌ها و افزونه‌های جانبی','Add-ons included'=>'افزودنی‌ها شامل می‌شوند','Add-ons restored successfully'=>'افزودنی‌ها با موفقیت بازیابی شدند','Additional Information'=>'اطلاعات بیشتر','Addon Installation Issue'=>'مشکل در نصب افزودنی','Address'=>'نشانی','Adds a small amount of CSS to the page, built from your own colours.'=>'مقدار کمی CSS بر اساس رنگ‌های انتخابی شما به برگه اضافه می‌کند.','Adds your form activity totals &ndash; forms, views and submissions &ndash; to the weekly email your site sends the main administrator. These totals are read on your own site and are never sent to WhiteStudio.'=>'مجموع فعالیت فرم‌های شما &ndash; فرم‌ها، بازدیدها و ارسال‌ها &ndash; را به ایمیل هفتگی که سایت برای مدیر اصلی می‌فرستد اضافه می‌کند. این آمار در سایت خودتان خوانده می‌شود و هرگز برای WhiteStudio ارسال نمی‌شود.','Admin Email'=>'ایمیل مدیر','Admin email'=>'ایمیل مدیر','Advance'=>'پیشرفته','Advanced'=>'پیشرفته','Advanced confirmation code Add-on'=>'افزودنی پیشرفته کد تأیید','Advanced features and advanced fields used in your forms will be disabled. Your forms, entries and settings will not be deleted, and will be available again if you upgrade.'=>'ویژگی‌های پیشرفته و فیلدهای پیشرفته استفاده‌شده در فرم‌های شما غیرفعال می‌شوند. فرم‌ها، ورودی‌ها و تنظیمات شما حذف نمی‌شوند و در صورت ارتقا دوباره در دسترس خواهند بود.','Advanced form fields'=>'فیلدهای پیشرفته فرم','Advanced integrations'=>'یکپارچه‌سازی‌های پیشرفته','After changing the Development Mode (Sandbox) option, save the settings, then deactivate and reactivate Easy Form Builder plugin from the Plugins page for the changes to take effect.'=>'پس از تغییر گزینه حالت توسعه (Sandbox)، تنظیمات را ذخیره کنید، سپس افزونه فرم‌ساز آسان را از صفحه افزونه‌ها غیرفعال و دوباره فعال کنید تا تغییرات اعمال شوند.','After submission, visitors can see aggregate survey results'=>'پس از ارسال، بازدیدکنندگان می‌توانند نتایج تجمیعی نظرسنجی را ببینند','Alert Email'=>'ایمیل هشدار','Alert!'=>'هشدار!','Align'=>'چینش','All'=>'همه','All SMS notifications sent by Easy Form Builder will be delivered to the numbers entered here.'=>'همه آگاه‌سازی‌های پیامکی ارسال‌شده توسط فرم‌ساز آسان به شماره‌هایی که اینجا وارد می‌شوند تحویل داده خواهند شد.','All form bindings removed.'=>'همه اتصال‌های فرم حذف شدند.','All formats'=>'همه قالب‌ها','All required add-ons were restored.'=>'همه افزودنی‌های ضروری بازیابی شدند.','Allowed'=>'مجاز','Alt Text'=>'متن جایگزین','An answer came back that could not be read, so delivery was not checked. Try again later.'=>'پاسخی دریافت شد که خوانده نشد، بنابراین تحویل بررسی نشد. بعداً دوباره تلاش کنید.','An auto-saved version exists'=>'یک نسخه ذخیره‌شده خودکار وجود دارد','An error occurred'=>'خطایی رخ داد','An error occurred. Please try again.'=>'خطایی رخ داد. لطفاً دوباره تلاش کنید.','Another reason'=>'دلیل دیگر','Any special instructions?'=>'دستورالعمل خاصی دارید؟','Anything you would like us to know'=>'هر نکته‌ای که می‌خواهید بدانیم','Application form for children’s library cards.'=>'فرم درخواست کارت کتابخانه کودکان','Apply'=>'اعمال','Arabic Date Picker'=>'انتخاب‌گر تاریخ عربی','Are you sure you want to close replies to this message?'=>'آیا مطمئن هستید که می‌خواهید پاسخ‌های این پیام را ببندید؟','Are you sure you want to delete'=>'آیا از حذف این مورد مطمئن هستید','Are you sure you want to delete this?'=>'مطمئنید که می‌خواهید این مورد را حذف کنید؟','Are you sure you want to duplicate the "%s" ?'=>'آیا مطمئن هستید که می‌خواهید %s را تکثیر کنید؟','Are you sure you want to open the responses to this message?'=>'آیا مطمئن هستید که می‌خواهید پاسخ‌های این پیام را باز کنید؟','Are you sure you want to reset the email template? This cannot be undone.'=>'آیا از بازنشانی قالب ایمیل مطمئن هستید؟ این عمل قابل بازگشت نیست.','Area Code'=>'پیش‌شماره','Ask a site administrator to install one of these plugins.'=>'از مدیر سایت بخواهید یکی از این افزونه‌ها را نصب کند.','Attach'=>'پیوست','Attempts made'=>'تلاش‌های انجام‌شده','Audio Recorder'=>'ضبط صدا','Audio Recording Forms'=>'فرم‌های ضبط صدا','Audio recording'=>'ضبط صدا','Audio, Video and Screen Recording Fields'=>'فیلدهای ضبط صدا، ویدئو و صفحه','Authenticated successfully, but listing Google Drive files failed: '=>'احراز هویت با موفقیت انجام شد، اما دریافت فهرست فایل‌های گوگل درایو ناموفق بود: ','Authentication'=>'احراز هویت','Authentication Type'=>'نوع احراز هویت','Authentication Value'=>'مقدار احراز هویت','Authentication failed. The JSON key may be invalid or corrupted, or your server clock is out of sync.'=>'احراز هویت ناموفق بود. ممکن است کلید JSON نامعتبر یا مخدوش باشد، یا ساعت سرور شما همگام‌سازی نشده باشد.','Auto-Populate'=>'پرکردن خودکار','Auto-Populate Add-on'=>'افزودنی پرکردن خودکار','Auto-Populate Dataset'=>'مجموعه‌داده پرکردن خودکار','Auto-Pop